SELECT COUNT(*)
FROM kb_comment
WHERE user_id = #{userId}

SELECT COUNT(*)
FROM kb_comment
WHERE document_id = #{documentId}

SELECT COUNT(*)
FROM kb_comment
WHERE created_at >= #{startDate}
AND created_at <= #{endDate}

SELECT DATE(created_at) AS date, COUNT(*) AS count
FROM kb_comment
WHERE created_at >= #{startDate}
AND created_at <= #{endDate}
GROUP BY DATE(created_at)
ORDER BY date ASC

SELECT COUNT(*)
FROM kb_comment
WHERE user_id = #{userId}
AND created_at >= #{startDate}
AND created_at <= #{endDate}

SELECT COUNT(*) / DATEDIFF(#{endDate}, #{startDate})
FROM kb_comment
WHERE created_at >= #{startDate}
AND created_at <= #{endDate}
